class Node {
	static STATES = {FREE: 0, OVER: 1, PRESSED: 2};	
	static MIN_RADIUS = 20;
	static MAX_RADIUS = 80;
	static PULSE_GROW = 10;

	constructor(id, x, y, parent, canvas){
		this.id = id;
		this.pos = createVector(x, y);
		this.parent = parent;
		this.canvas = canvas;

		this.radius = Node.MIN_RADIUS * 2;

		this.pulseRadius = 0;
		this.pulsed = false;

		this._events = {};

		this.children = [];
		if(this.parent !== null){
			this.color = color(
				constrain(this.parent.color._getRed() + random(-80, 80), 0, 255),
				constrain(this.parent.color._getGreen() + random(-80, 80), 0, 255),
				constrain(this.parent.color._getBlue() + random(-80, 80), 0, 255)
			);
			this.parent.children.push(this);
		}else{
			this.color = color(random(255), random(255), random(255));
		}

		this.overColor = color(
			constrain(this.color._getRed() + 60, 0, 255),
			constrain(this.color._getGreen() + 60, 0, 255),
			constrain(this.color._getBlue() + 60, 0, 255)
		);

		this.pressColor = color(
			constrain(this.color._getRed() - 30, 0, 255),
			constrain(this.color._getGreen() - 30, 0, 255),
			constrain(this.color._getBlue() - 30, 0, 255)
		);

		this.state = Node.STATES.FREE;
	}

	draw(selected){
		if(this.children.length > 0){
			this.canvas.strokeWeight(1);
			this.canvas.stroke(this.pressColor);
			this.canvas.noFill();
			this.canvas.circle(this.pos.x, this.pos.y, this.pulseRadius);

			this.children.forEach(c => {
				var distance = 2 * dist(this.pos.x, this.pos.y, c.pos.x, c.pos.y);
				if(distance > this.pulseRadius && distance < this.pulseRadius + Node.PULSE_GROW){
					c.pulse();
				}
			});

			this.pulseRadius += Node.PULSE_GROW;
		}

		this.canvas.strokeWeight(4);
		this.canvas.stroke(this.color);
		if(this.state == Node.STATES.PRESSED || selected || frameCount - this.pulsed < 8)
			this.canvas.fill(this.pressColor);
		else if(this.state == Node.STATES.FREE)
			this.canvas.fill(255);
		else if(this.state == Node.STATES.OVER)
			this.canvas.fill(this.overColor);

		var destRadius = this.destRadius;
		if(frameCount - this.pulsed < 8){
			destRadius += 30;
		}
		this.radius += (destRadius - this.radius) * 0.09;

		this.canvas.circle(this.pos.x, this.pos.y, this.radius-4);

		this.canvas.strokeWeight(1);
		this.canvas.stroke(this.pressColor);
		this.canvas.circle(this.pos.x, this.pos.y, this.radius-6);
	}

	mouseMoved(x, y){
		var distance = dist(this.pos.x, this.pos.y, x, y);
		if(distance < this.radius/2){
			this.state = Node.STATES.OVER;
			this.destRadius = this.originalRadius * 1.5;
			cursor(HAND);
		}else{
			this.state = Node.STATES.FREE;
			this.destRadius = this.originalRadius;
		}
	}

	mousePressed(x, y){
		var distance = dist(this.pos.x, this.pos.y, x, y);
		if(distance < this.radius/2){
			this.state = Node.STATES.PRESSED;
			this.dragged = false;
		}
	}

	mouseDragged(x, y){
		if(this.state == Node.STATES.PRESSED){
			this.dragged = true;
			this.pos.x += x;
			this.pos.y += y;
		}
	}

	mouseReleased(x, y){

	}

	pulse(){
		this.pulseRadius = 0;
		this.pulsed = frameCount;
		this.emit('pulse', this);
	}

	//event emitter
	on(name, listener) {
    if (!this._events[name]) {
      this._events[name] = [];
    }

    this._events[name].push(listener);
  }

	removeListener(name, listenerToRemove) {
    if (!this._events[name]) {
      throw new Error(`Can't remove a listener. Event "${name}" doesn't exits.`);
    }
    const filterListeners = (listener) => listener !== listenerToRemove;
    this._events[name] = this._events[name].filter(filterListeners);
  }

	emit(name, data) {
    if (!this._events[name]) {
      throw new Error(`Can't emit an event. Event "${name}" doesn't exits.`);
    }
    const fireCallbacks = (callback) => {
      callback(data);
    };
    this._events[name].forEach(fireCallbacks);
  }
}

