var tree;
var graphics;

var osc, envelope;
const loopInFrames = 240;

function setup() {
	var renderer = createCanvas(windowWidth, windowHeight);
	graphics = createGraphics(width, height);
	tree = new Tree(graphics);
	tree.addNew(0, width/2, height/2, null);
	tree.on("pulse", onPulse);

	osc = new p5.SinOsc();
  envelope = new p5.Env();
  envelope.setADSR(0.001, 0.5, 0.1, 0.5);
  envelope.setRange(1, 0);
  osc.start();
}

function draw() {
	graphics.background(255, 255, 220);	
	tree.draw();
	image(graphics, 0, 0);

	if (frameCount % loopInFrames === 0 || frameCount === 1) {
		tree.pulse();
  }
}

function onPulse(data){
	var angle = 0;
	if(data.parent){
		angle =  Math.atan2(data.parent.pos.y - data.pos.y, data.parent.pos.x - data.pos.x);
		if(angle < 0) angle += TWO_PI;
	}
	var note = Math.floor((angle / TWO_PI) * 12);
	let midiValue = 60 + note;
	let freqValue = midiToFreq(midiValue);

	osc.freq(freqValue);
	envelope.play(osc, 0, 0.1);
}

function mouseMoved(){
	tree.mouseMoved();
}

function mouseDragged(){
	tree.mouseDragged();
}

function mousePressed(){
	tree.mousePressed();
}

function mouseReleased(){
	tree.mouseReleased();
}

